+function nestedIndexedMap(depth, offsetLine) {
+  var map = { version: 3, sources: ['a.js'], sourcesContent: ['a'], names: [], mappings: 'AAAA' };
+  for (var i = 0; i < depth; i++) {
+    map = { version: 3, sections: [{ offset: { line: offsetLine, column: 0 }, map: map }] };
+  }
+  return map;
+}
